(function mergeCatalog() {
  const existingNames = new Set(QUESTS.map(quest => quest.name));
  const idByName = new Map(QUESTS.map(quest => [quest.name, quest.id]));
  CATALOG_RECORDS.forEach(record => { if (!existingNames.has(record.name)) idByName.set(record.name, record.id); });

  CATALOG_RECORDS.forEach(record => {
    if (existingNames.has(record.name)) return;
    const parsed = CATALOG_DETAILS[record.id];
    const sourceKey = `catalog_${record.id.slice(8)}`;
    SOURCES[sourceKey] = {name:`魔力百科｜${record.name}`,url:record.sourceUrl};
    const prerequisites = [...new Set([
      ...record.prereqNames.map(name => idByName.get(name)).filter(Boolean),
      ...parsed.linkedPrerequisites.map(id => idByName.get(CATALOG_RECORDS.find(item => item.id === id)?.name) || id).filter(Boolean)
    ])].filter(id => id !== record.id);
    const rewardSummary = [...parsed.rewards.guaranteed, ...parsed.rewards.chance, ...parsed.rewards.related].slice(0, 2).join('；') || '原攻略未单列任务奖励';
    QUESTS.push({
      id:record.id,name:record.name,aliases:record.aliases,initials:'',series:record.series,
      order:record.order,level:parsed.info['建议等级'] || record.level,
      type:record.scope === '通用任务' ? '通用任务' : (record.scope === '怀旧服不可用' ? record.scope : '怀旧服任务'),
      prerequisites,
      summary:[parsed.info['必要条件'] && `必要条件：${parsed.info['必要条件']}`, record.scope !== '通用任务' && record.scope !== '怀旧服不可用' && '以下仅展示怀旧服路线与参数'].filter(Boolean).join('；'),
      reward:rewardSummary,source:sourceKey,reliability:'high',detailStatus:'parsed',
      bossStatus:parsed.bosses.length ? 'documented' : 'not-documented'
    });
    QUEST_GUIDES[record.id] = parsed.guide;
    BOSS_GUIDES[record.id] = parsed.bosses;
    REWARD_GUIDES[record.id] = parsed.rewards;
    existingNames.add(record.name);
  });
})();
